-- Negocios de demostración (ficticios)
INSERT OR REPLACE INTO businesses (id,name,color,greeting_es,greeting_ca,greeting_en,chips_es,chips_ca,chips_en,knowledge,demo,active) VALUES ('demo-dental','Clínica Dental Lumen','#0e8f86','¡Hola! Soy el asistente de Clínica Dental Lumen. Puedo informarte de horarios, precios y tratamientos, o ayudarte a pedir cita. ¿En qué te ayudo?','Hola! Sóc l''assistent de Clínica Dental Lumen. Et puc informar d''horaris, preus i tractaments, o ajudar-te a demanar cita. En què t''ajudo?','Hi! I''m the assistant of Clínica Dental Lumen. I can tell you about opening hours, prices and treatments, or help you book an appointment.','["¿Cuánto cuesta una limpieza?", "Me duele una muela", "¿Qué horario tenéis?", "Quiero pedir cita"]','["Quant costa una neteja?", "Em fa mal un queixal", "Quin horari teniu?", "Vull demanar cita"]','["How much is a cleaning?", "I have toothache", "Opening hours?", "Book an appointment"]','Negocio ficticio de demostración: Clínica Dental Lumen.
Dirección: calle Mayor, 24 (ciudad de ejemplo). Parking público a 50 metros. Metro a 3 minutos a pie.
Horario: de lunes a viernes de 9:00 a 20:00; sábados de 9:00 a 14:00; domingos cerrado.
Teléfono de la clínica: 930 000 000 (ficticio).
Precios:
- Primera visita con revisión y diagnóstico: gratuita.
- Limpieza dental: 45 €.
- Blanqueamiento: desde 180 €.
- Empaste: desde 55 €.
- Ortodoncia (brackets o invisible) e implantes: presupuesto personalizado tras la primera visita.
Urgencias: se reservan huecos cada día para urgencias (dolor, inflamación, dientes rotos). Si el cliente tiene dolor, ofrecer cita hoy mismo pidiendo nombre y teléfono.
Pago: tarjeta, efectivo o Bizum. Financiación sin intereses hasta 12 meses para tratamientos de más de 300 €. Trabajamos con las principales mutuas (Adeslas, Sanitas, DKV y Asisa).
Equipo: 3 odontólogos, 1 ortodoncista y 2 higienistas.
Idiomas de atención en la clínica: castellano, catalán e inglés.',1,1);
INSERT OR REPLACE INTO businesses (id,name,color,greeting_es,greeting_ca,greeting_en,chips_es,chips_ca,chips_en,knowledge,demo,active) VALUES ('demo-gimnasio','Gimnàs Impuls','#d4501e','¡Hola! Soy el asistente de Gimnàs Impuls. Pregúntame por cuotas, clases u horarios, o te consigo un día de prueba gratis.','Hola! Sóc l''assistent de Gimnàs Impuls. Pregunta''m per quotes, classes o horaris, o et consegueixo un dia de prova gratuït.','Hi! I''m the assistant of Gimnàs Impuls. Ask me about memberships, classes or opening hours, or get a free trial day.','["¿Cuánto cuesta la cuota?", "¿Qué clases hay?", "¿Tiene permanencia?", "Quiero probar un día"]','["Quant costa la quota?", "Quines classes hi ha?", "Hi ha permanència?", "Vull provar un dia"]','["How much is it?", "What classes are there?", "Is there a minimum stay?", "Free trial day"]','Negocio ficticio de demostración: Gimnàs Impuls.
Dirección: avenida del Parque, 8 (ciudad de ejemplo). Los socios tienen 2 horas de parking gratuito.
Horario: de lunes a viernes de 6:30 a 23:00; sábados, domingos y festivos de 8:00 a 21:00.
Cuotas:
- Mensual: 39 € al mes.
- Anual: 34 € al mes (pago anual de 408 €).
- Estudiantes y mayores de 65: 29 € al mes.
- Este mes no se cobra matrícula (normalmente 30 €).
- Todas las clases dirigidas están incluidas en la cuota.
Sin permanencia: baja cuando quieras desde la app o en recepción, avisando antes del día 25 del mes.
Clases: más de 60 clases semanales: spinning, yoga, pilates, body pump, boxeo, zumba y entrenamiento funcional. Se reservan desde la app del gimnasio.
Instalaciones: sala de musculación, zona cardio, 2 salas de clases, piscina climatizada de 20 metros, sauna y vestuarios con taquillas.
Entrenamiento personal: sesiones desde 30 €; la primera sesión de valoración es gratuita. Hay nutricionista (consulta de 35 €).
Día de prueba: gratis. Para reservarlo, pedir nombre y teléfono.',1,1);
INSERT OR REPLACE INTO businesses (id,name,color,greeting_es,greeting_ca,greeting_en,chips_es,chips_ca,chips_en,knowledge,demo,active) VALUES ('demo-inmobiliaria','Inmobiliaria Horizonte','#6d4bd8','¡Hola! Soy el asistente de Inmobiliaria Horizonte. ¿Buscas comprar, alquilar o vender una vivienda?','Hola! Sóc l''assistent d''Inmobiliaria Horizonte. Busques comprar, llogar o vendre un habitatge?','Hi! I''m the assistant of Inmobiliaria Horizonte. Are you looking to buy, rent or sell a home?','["Quiero vender mi piso", "Busco piso de alquiler", "¿Me ayudáis con la hipoteca?", "Quiero visitar un piso"]','["Vull vendre el meu pis", "Busco pis de lloguer", "M''ajudeu amb la hipoteca?", "Vull visitar un pis"]','["I want to sell my flat", "Flats for rent", "Mortgage help", "Book a viewing"]','Negocio ficticio de demostración: Inmobiliaria Horizonte.
Oficina: plaza de la Iglesia, 3 (ciudad de ejemplo).
Horario: de lunes a viernes de 9:30 a 14:00 y de 16:30 a 20:00; sábados por la mañana solo con cita previa.
Venta: más de 120 viviendas en venta en la zona, de 140.000 € a 650.000 €. Para enviar una selección personalizada, pedir nombre, teléfono, número de habitaciones y presupuesto.
Alquiler: pisos desde 850 € al mes. Requisitos: nómina o contrato de trabajo y fianza de dos mensualidades. No se cobran honorarios al inquilino.
Vender tu vivienda: valoración gratuita en 48 horas con datos reales de ventas de la zona. Honorarios de venta: 3 % + IVA, solo si se vende. Reportaje fotográfico profesional y vídeo incluidos.
Hipotecas: asesor financiero propio que compara ofertas de varios bancos sin coste para el cliente.
Visitas: se organizan cuando le vaya mejor al cliente, también por la tarde. Para concertarla, pedir nombre y teléfono.',1,1);
